import React, { useState, useEffect, useCallback, useRef } from 'react';
import { scrollableTabsSx } from '../constants/appShellLayout';
import {
  Typography,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Alert,
  Paper,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  CircularProgress,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Switch,
  FormControlLabel,
  IconButton
} from '@mui/material';
import {
  Security as SecurityIcon,
  DataUsage as DataIcon,
  Settings as SettingsIcon,
  Download as DownloadIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  CheckCircle as CheckIcon,
  Warning as WarningIcon,
  Info as InfoIcon,
  Visibility as ViewIcon,
  Timeline as TimelineIcon,
  Add as AddIcon
} from '@mui/icons-material';
import { useForm, Controller } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import apiService from '../services/api';
import { useNotification } from '../context/NotificationContext';
import TabSectionNavLinks from './TabSectionNavLinks';
import AdminDsarOpsPanel from './compliance/AdminDsarOpsPanel';
import { isAdminUserProfile } from '../utils/authRole';
import ScrollableTableContainer from './shared/ScrollableTableContainer';
import WorkspacePageHeader from './shared/WorkspacePageHeader';

const DATA_PRIVACY_TAB_LABELS = [
  'Privacy Overview',
  'Data Requests',
  'Activity Log',
  'Consent Management',
  'Security Settings',
] as const;

// Data privacy consent schema
const consentSchema = yup.object({
  dataProcessing: yup.boolean().required(),
  marketingCommunications: yup.boolean().required(),
  thirdPartySharing: yup.boolean().required(),
  analyticsTracking: yup.boolean().required(),
  cookieConsent: yup.boolean().required(),
  dataRetention: yup.boolean().required()
});

type ConsentForm = yup.InferType<typeof consentSchema>;

interface DataRequest {
  _id: string;
  type: 'access' | 'portability' | 'deletion' | 'rectification' | 'restriction';
  status: 'pending' | 'in_progress' | 'completed' | 'rejected';
  description: string;
  requestedAt: string;
  completedAt?: string;
  response?: string;
}

interface DataActivity {
  _id: string;
  action: string;
  dataType: string;
  timestamp?: string;
  createdAt?: string;
  ipAddress: string;
  userAgent: string;
  details: string;
}

type LoadStatus = 'idle' | 'loading' | 'ready' | 'error';

interface SecurityPreferences {
  twoFactorAuth: boolean;
  sessionTimeout: number;
  dataEncryption: boolean;
  auditLogging: boolean;
}



interface PrivacySettings {
  dataProcessing: boolean;
  marketingCommunications: boolean;
  thirdPartySharing: boolean;
  analyticsTracking: boolean;
  cookieConsent: boolean;
  dataRetention: boolean;
  twoFactorAuth: boolean;
  sessionTimeout: number;
  dataEncryption: boolean;
  auditLogging: boolean;
}

function formatPrivacyDate(dateString?: string) {
  if (!dateString) return 'Date unavailable';
  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) return 'Date unavailable';
  return date.toLocaleString('en-IN', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function activityDate(activity: Pick<DataActivity, 'timestamp' | 'createdAt'>) {
  return formatPrivacyDate(activity.timestamp || activity.createdAt);
}

function securityPreferencesFrom(settings: PrivacySettings): SecurityPreferences {
  return {
    twoFactorAuth: settings.twoFactorAuth,
    sessionTimeout: settings.sessionTimeout,
    dataEncryption: settings.dataEncryption,
    auditLogging: settings.auditLogging,
  };
}

function flattenPrivacySettingsPayload(raw: any): PrivacySettings {
  const nested = raw?.settings && typeof raw.settings === 'object' ? raw.settings : {};
  const flat = { ...nested, ...(raw || {}) } as PrivacySettings;
  delete (flat as any).settings;
  delete (flat as any)._id;
  delete (flat as any).__v;
  delete (flat as any).userId;
  delete (flat as any).requests;
  delete (flat as any).activities;
  return {
    dataProcessing: flat.dataProcessing ?? true,
    marketingCommunications: flat.marketingCommunications ?? false,
    thirdPartySharing: flat.thirdPartySharing ?? false,
    analyticsTracking: flat.analyticsTracking ?? true,
    cookieConsent: flat.cookieConsent ?? true,
    dataRetention: flat.dataRetention ?? true,
    twoFactorAuth: flat.twoFactorAuth ?? false,
    sessionTimeout: flat.sessionTimeout ?? 30,
    dataEncryption: flat.dataEncryption ?? true,
    auditLogging: flat.auditLogging ?? true,
  };
}


const DataPrivacy: React.FC = () => {
  const { notifySuccess, notifyError } = useNotification();
  const [activeTab, setActiveTab] = useState(0);
  const [privacySettings, setPrivacySettings] = useState<PrivacySettings | null>(null);
  const [securityDraft, setSecurityDraft] = useState<SecurityPreferences | null>(null);
  const [settingsStatus, setSettingsStatus] = useState<LoadStatus>('loading');
  const [settingsError, setSettingsError] = useState<string | null>(null);
  const [dataRequests, setDataRequests] = useState<DataRequest[]>([]);
  const [requestsStatus, setRequestsStatus] = useState<LoadStatus>('idle');
  const [requestsError, setRequestsError] = useState<string | null>(null);
  const [dataActivities, setDataActivities] = useState<DataActivity[]>([]);
  const [activitiesStatus, setActivitiesStatus] = useState<LoadStatus>('idle');
  const [activitiesError, setActivitiesError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isSavingSecurity, setIsSavingSecurity] = useState(false);
  const [isSubmittingRequest, setIsSubmittingRequest] = useState(false);
  const [openRequestDialog, setOpenRequestDialog] = useState(false);
  const [openSettingsDialog, setOpenSettingsDialog] = useState(false);
  const [requestFormType, setRequestFormType] = useState('');
  const [requestFormDescription, setRequestFormDescription] = useState('');
  const [selectedRequest, setSelectedRequest] = useState<DataRequest | null>(null);
  const [openRequestDetailsDialog, setOpenRequestDetailsDialog] = useState(false);
  const [requestFormError, setRequestFormError] = useState<string | null>(null);
  const [dsarSummary, setDsarSummary] = useState<{
    framework?: string;
    openRequestCount?: number;
    erasureRequestCount?: number;
    dsarReady?: boolean;
    guidance?: string;
    supportedRequestTypes?: string[];
    consentPosture?: Record<string, boolean | null>;
  } | null>(null);
  const [dsarStatus, setDsarStatus] = useState<LoadStatus>('idle');
  const [dsarError, setDsarError] = useState<string | null>(null);
  const [dsarBusy, setDsarBusy] = useState(false);
  const settingsLoadedRef = useRef(false);
  const submittingRequestRef = useRef(false);

  const {
    control,
    handleSubmit,
    reset,
  } = useForm<ConsentForm>({
    resolver: yupResolver(consentSchema),
    defaultValues: {
      dataProcessing: true,
      marketingCommunications: false,
      thirdPartySharing: false,
      analyticsTracking: true,
      cookieConsent: true,
      dataRetention: true
    }
  });

  const loadPrivacySettings = useCallback(async () => {
    if (!settingsLoadedRef.current) {
      setSettingsStatus('loading');
    }
    setSettingsError(null);
    try {
      const settingsData = await apiService.getPrivacySettings() as any;
      if (settingsData?.success && settingsData.data) {
        const flattened = flattenPrivacySettingsPayload(settingsData.data);
        setPrivacySettings(flattened);
        setSecurityDraft(securityPreferencesFrom(flattened));
        reset(flattened);
        settingsLoadedRef.current = true;
        setSettingsStatus('ready');
      } else {
        const message = settingsData?.message || 'Failed to load privacy settings.';
        setSettingsError(message);
        if (!settingsLoadedRef.current) setSettingsStatus('error');
      }
    } catch (error) {
      console.error('Error loading privacy settings:', error);
      setSettingsError(error instanceof Error ? error.message : 'Failed to load privacy settings.');
      if (!settingsLoadedRef.current) setSettingsStatus('error');
    }
  }, [reset]);

  const loadDataRequests = useCallback(async () => {
    setRequestsStatus('loading');
    setRequestsError(null);
    try {
      const requestsData = await apiService.getDataRequests() as any;
      if (requestsData?.success) {
        setDataRequests(Array.isArray(requestsData.data) ? requestsData.data : []);
        setRequestsStatus('ready');
      } else {
        setRequestsError(requestsData?.message || 'Failed to load data requests.');
        setRequestsStatus('error');
      }
    } catch (error) {
      console.error('Error loading data requests:', error);
      setRequestsError(error instanceof Error ? error.message : 'Failed to load data requests.');
      setRequestsStatus('error');
    }
  }, []);

  const loadDataActivities = useCallback(async () => {
    setActivitiesStatus('loading');
    setActivitiesError(null);
    try {
      const activitiesData = await apiService.getDataActivities() as any;
      if (activitiesData?.success) {
        setDataActivities(Array.isArray(activitiesData.data) ? activitiesData.data : []);
        setActivitiesStatus('ready');
      } else {
        setActivitiesError(activitiesData?.message || 'Failed to load the activity log.');
        setActivitiesStatus('error');
      }
    } catch (error) {
      console.error('Error loading data activities:', error);
      setActivitiesError(error instanceof Error ? error.message : 'Failed to load the activity log.');
      setActivitiesStatus('error');
    }
  }, []);

  const loadDsarSummary = useCallback(async () => {
    setDsarStatus('loading');
    setDsarError(null);
    try {
      const dsarData = await apiService.getDpdpDsarSummary() as any;
      if (dsarData?.success) {
        setDsarSummary(dsarData.data ?? null);
        setDsarStatus('ready');
      } else {
        setDsarError(dsarData?.message || 'Failed to load the DSAR summary.');
        setDsarStatus('error');
      }
    } catch (error) {
      console.error('Error loading DSAR summary:', error);
      setDsarError(error instanceof Error ? error.message : 'Failed to load the DSAR summary.');
      setDsarStatus('error');
    }
  }, []);

  const refreshPrivacySurfaces = useCallback(async () => {
    await Promise.all([
      loadPrivacySettings(),
      loadDsarSummary(),
      loadDataRequests(),
      loadDataActivities(),
    ]);
  }, [loadPrivacySettings, loadDsarSummary, loadDataRequests, loadDataActivities]);

  useEffect(() => {
    void loadPrivacySettings();
  }, [loadPrivacySettings]);

  // Secondary privacy surfaces load only when their tab is opened.
  useEffect(() => {
    if (activeTab === 0) {
      void loadDsarSummary();
    }
    if (activeTab === 1) {
      void loadDataRequests();
    }
    if (activeTab === 2) {
      void loadDataActivities();
    }
  }, [activeTab, loadDsarSummary, loadDataRequests, loadDataActivities]);

  const savePrivacySettings = async (formData: ConsentForm) => {
    setIsSaving(true);
    try {
      const data = await apiService.updatePrivacySettings(formData) as any;
      if (data?.success) {
        setPrivacySettings((current) => (current ? { ...current, ...formData } : current));
        setOpenSettingsDialog(false);
        notifySuccess('Privacy settings updated successfully!');
      } else {
        notifyError(data?.message || 'Failed to update privacy settings');
      }
    } catch (error) {
      console.error('Error saving privacy settings:', error);
      notifyError(error instanceof Error ? error.message : 'Failed to update privacy settings');
    } finally {
      setIsSaving(false);
    }
  };

  const submitDataRequest = async (requestData: { type: string; description: string }) => {
    if (submittingRequestRef.current) return;
    submittingRequestRef.current = true;
    setIsSubmittingRequest(true);
    setRequestFormError(null);
    try {
      const data = await apiService.submitDataRequest(requestData) as any;
      if (data?.success) {
        setOpenRequestDialog(false);
        setRequestFormType('');
        setRequestFormDescription('');
        notifySuccess('Data request submitted successfully!');
        void refreshPrivacySurfaces();
      } else {
        const message = data?.message || 'Failed to submit data request';
        setRequestFormError(message);
        notifyError(message);
      }
    } catch (error) {
      console.error('Error submitting data request:', error);
      const message = error instanceof Error ? error.message : 'Failed to submit data request';
      setRequestFormError(message);
      notifyError(message);
    } finally {
      submittingRequestRef.current = false;
      setIsSubmittingRequest(false);
    }
  };

  const downloadPersonalData = async () => {
    try {
      const data = await apiService.downloadPersonalData() as any;
      if (data?.success) {
        const blob = new Blob([JSON.stringify(data.data, null, 2)], { type: 'application/json' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `personal-data-${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
        notifySuccess('Personal data download started.');
      } else {
        notifyError(data?.message || 'Failed to download personal data');
      }
    } catch (error) {
      console.error('Error downloading personal data:', error);
      notifyError(error instanceof Error ? error.message : 'Failed to download personal data');
    }
  };

  const getRequestTypeLabel = (type: string) => {
    const types: { [key: string]: string } = {
      access: 'Data Access Request (DPDP)',
      portability: 'Data Portability Request',
      data_portability: 'Data Portability Request (DPDP)',
      deletion: 'Data Deletion Request',
      erasure: 'Erasure Request (DPDP)',
      delete: 'Data Deletion Request',
      rectification: 'Data Rectification Request',
      correction: 'Correction Request (DPDP)',
      restriction: 'Data Processing Restriction',
      grievance: 'Privacy Grievance (DPDP)',
      consent_withdrawal: 'Consent Withdrawal (DPDP)',
    };
    return types[type] || type;
  };

  const acknowledgeErasure = async (requestId: string) => {
    setDsarBusy(true);
    try {
      const data = await apiService.acknowledgeDpdpErasure(requestId) as any;
      if (data.success) {
        notifySuccess('Erasure request acknowledged.');
        await refreshPrivacySurfaces();
        setOpenRequestDetailsDialog(false);
      } else {
        notifyError(data.message || 'Failed to acknowledge erasure request');
      }
    } catch (error) {
      notifyError('Failed to acknowledge erasure request');
    } finally {
      setDsarBusy(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'success';
      case 'rejected': return 'error';
      case 'in_progress': return 'warning';
      case 'pending': return 'info';
      default: return 'default';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'completed': return <CheckIcon />;
      case 'rejected': return <WarningIcon />;
      case 'in_progress': return <TimelineIcon />;
      case 'pending': return <InfoIcon />;
      default: return <InfoIcon />;
    }
  };

  const saveSecurityPreferences = async () => {
    if (!securityDraft || isSavingSecurity) return;
    setIsSavingSecurity(true);
    try {
      const data = await apiService.updatePrivacySettings({
        twoFactorAuth: securityDraft.twoFactorAuth,
        sessionTimeout: securityDraft.sessionTimeout,
        dataEncryption: securityDraft.dataEncryption,
        auditLogging: securityDraft.auditLogging,
      }) as any;
      if (data?.success) {
        setPrivacySettings((current) => (current ? { ...current, ...securityDraft } : current));
        notifySuccess('Security preferences saved.');
      } else {
        notifyError(data?.message || 'Failed to save security preferences');
      }
    } catch (error) {
      console.error('Error saving security preferences:', error);
      notifyError(error instanceof Error ? error.message : 'Failed to save security preferences');
    } finally {
      setIsSavingSecurity(false);
    }
  };

  const settingsBlocked = settingsStatus !== 'ready' || !privacySettings;

  return (
    <Box>
      <WorkspacePageHeader
        title="Data privacy"
        description="Controls govern how personal or commercial identifiers attached to transactions and documents may be processed."
      />
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', mb: 3, flexWrap: 'wrap', gap: 1 }}>
        <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, gap: 1, width: { xs: '100%', sm: 'auto' } }}>
          <Button
            variant="contained"
            startIcon={<SettingsIcon />}
            onClick={() => setOpenSettingsDialog(true)}
            fullWidth
            sx={{ width: { xs: '100%', sm: 'auto' } }}
          >
            Privacy Settings
          </Button>
          <Button
            variant="outlined"
            startIcon={<DownloadIcon />}
            onClick={downloadPersonalData}
            fullWidth
            sx={{ width: { xs: '100%', sm: 'auto' } }}
          >
            Download My Data
          </Button>
        </Box>
      </Box>

      <Box sx={{ mb: 3 }}>
        <Tabs
          value={activeTab}
          onChange={(_event, newValue) => setActiveTab(newValue)}
          variant="scrollable"
          scrollButtons="auto"
          allowScrollButtonsMobile
          aria-label="Data privacy sections"
          sx={scrollableTabsSx}
        >
          {DATA_PRIVACY_TAB_LABELS.map((label, index) => (
            <Tab
              key={label}
              label={label}
              id={`data-privacy-tab-${index}`}
              aria-controls={`data-privacy-panel-${index}`}
            />
          ))}
        </Tabs>
        <TabSectionNavLinks
          tabLabels={[...DATA_PRIVACY_TAB_LABELS]}
          currentIndex={activeTab}
          onNavigate={setActiveTab}
        />
      </Box>

      {/* Privacy Overview Tab */}
      {activeTab === 0 && (
        <Grid container spacing={3} role="tabpanel" id="data-privacy-panel-0" aria-labelledby="data-privacy-tab-0">
          {dsarStatus === 'loading' ? (
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', justifyContent: 'center', py: 1 }}>
                <CircularProgress size={24} aria-label="Loading DSAR summary" />
              </Box>
            </Grid>
          ) : null}
          {dsarStatus === 'error' ? (
            <Grid item xs={12}>
              <Alert severity="error" action={<Button size="small" onClick={() => { void loadDsarSummary(); }}>Retry</Button>}>
                {dsarError || 'Failed to load the DSAR summary.'}
              </Alert>
            </Grid>
          ) : null}
          {dsarStatus === 'ready' && dsarSummary ? (
            <Grid item xs={12}>
              <Alert severity={dsarSummary.dsarReady ? 'success' : 'warning'} sx={{ mb: 1 }}>
                DPDP DSAR posture: {dsarSummary.openRequestCount ?? 0} open request(s).
                {dsarSummary.guidance ? ` ${dsarSummary.guidance}` : ''}
              </Alert>
            </Grid>
          ) : null}
          {settingsStatus === 'error' && !privacySettings ? (
            <Grid item xs={12}>
              <Alert severity="error" action={<Button size="small" onClick={() => { void loadPrivacySettings(); }}>Retry</Button>}>
                {settingsError || 'Failed to load privacy settings.'}
              </Alert>
            </Grid>
          ) : null}
          {settingsStatus === 'loading' && !privacySettings ? (
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
                <CircularProgress aria-label="Loading privacy settings" />
              </Box>
            </Grid>
          ) : null}
          {isAdminUserProfile() ? (
            <Grid item xs={12}>
              <AdminDsarOpsPanel />
            </Grid>
          ) : null}
          {privacySettings ? (
            <>
          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <SecurityIcon color="primary" sx={{ mr: 1 }} />
                  <Typography variant="h6">
                    Data Protection Status
                  </Typography>
                </Box>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  These are stored preferences from the last successful load or save. They do not show live MFA, encryption, or audit enforcement.
                </Typography>
                <List dense>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.dataEncryption ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Data encryption preference"
                      secondary={privacySettings.dataEncryption ? 'On — stored preference, not a live encryption control.' : 'Off — stored preference, not a live encryption control.'}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.twoFactorAuth ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Two-factor preference"
                      secondary={privacySettings.twoFactorAuth ? 'On — stored preference. Login MFA is separate.' : 'Off — stored preference. Login MFA is separate.'}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.auditLogging ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Audit logging preference"
                      secondary={privacySettings.auditLogging ? 'On — stored preference. This does not start or stop activity recording.' : 'Off — stored preference. This does not start or stop activity recording.'}
                    />
                  </ListItem>
                </List>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <DataIcon color="primary" sx={{ mr: 1 }} />
                  <Typography variant="h6">
                    Data Processing Consent
                  </Typography>
                </Box>
                <List dense>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.dataProcessing ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Data Processing"
                      secondary={privacySettings.dataProcessing ? 'Consented' : 'Not consented'}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.marketingCommunications ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Marketing Communications"
                      secondary={privacySettings.marketingCommunications ? 'Consented' : 'Not consented'}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.thirdPartySharing ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Third-Party Sharing"
                      secondary={privacySettings.thirdPartySharing ? 'Consented' : 'Not consented'}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.analyticsTracking ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Analytics Tracking"
                      secondary={privacySettings.analyticsTracking ? 'Consented' : 'Not consented'}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.cookieConsent ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Cookie Consent"
                      secondary={privacySettings.cookieConsent ? 'Consented' : 'Not consented'}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      {privacySettings.dataRetention ? <CheckIcon color="success" /> : <WarningIcon color="warning" />}
                    </ListItemIcon>
                    <ListItemText
                      primary="Data Retention"
                      secondary={privacySettings.dataRetention ? 'Consented' : 'Not consented'}
                    />
                  </ListItem>
                </List>
              </CardContent>
            </Card>
          </Grid>
            </>
          ) : null}

          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Quick Actions
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={4}>
                    <Button
                      variant="outlined"
                      fullWidth
                      startIcon={<DeleteIcon />}
                      onClick={() => {
                        setRequestFormType('erasure');
                        setRequestFormError(null);
                        setOpenRequestDialog(true);
                      }}
                    >
                      Request Deletion
                    </Button>
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <Button
                      variant="outlined"
                      fullWidth
                      startIcon={<EditIcon />}
                      onClick={() => {
                        setRequestFormType('correction');
                        setRequestFormError(null);
                        setOpenRequestDialog(true);
                      }}
                    >
                      Request Correction
                    </Button>
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <Button
                      variant="outlined"
                      fullWidth
                      startIcon={<SettingsIcon />}
                      onClick={() => setOpenSettingsDialog(true)}
                    >
                      Update Settings
                    </Button>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Data Requests Tab */}
      {activeTab === 1 && (
        <Grid container spacing={3} role="tabpanel" id="data-privacy-panel-1" aria-labelledby="data-privacy-tab-1">
          <Grid item xs={12}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="h6">
                Data Subject Requests
              </Typography>
              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={() => {
                  setRequestFormType('');
                  setRequestFormError(null);
                  setOpenRequestDialog(true);
                }}
              >
                New Request
              </Button>
            </Box>
          </Grid>

          {requestsStatus === 'loading' || requestsStatus === 'idle' ? (
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
                <CircularProgress aria-label="Loading data requests" />
              </Box>
            </Grid>
          ) : requestsStatus === 'error' ? (
            <Grid item xs={12}>
              <Alert severity="error" action={<Button size="small" onClick={() => { void loadDataRequests(); }}>Retry</Button>}>
                {requestsError || 'Failed to load data requests.'}
              </Alert>
            </Grid>
          ) : dataRequests.length === 0 ? (
            <Grid item xs={12}>
              <Alert severity="info">
                No data requests found. Submit a request to access, correct, or delete your personal data.
              </Alert>
            </Grid>
          ) : (
            <Grid item xs={12}>
              <ScrollableTableContainer component={Paper}>
                <Table sx={{ minWidth: 640 }}>
                  <TableHead>
                    <TableRow>
                      <TableCell>Request Type</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell>Requested Date</TableCell>
                      <TableCell>Description</TableCell>
                      <TableCell>Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {dataRequests.map((request) => (
                      <TableRow key={request._id}>
                        <TableCell>
                          <Typography variant="body2">
                            {getRequestTypeLabel(request.type)}
                          </Typography>
                        </TableCell>
                        <TableCell>
                          <Chip
                            icon={getStatusIcon(request.status)}
                            label={request.status.replace('_', ' ').toUpperCase()}
                            color={getStatusColor(request.status) as any}
                            size="small"
                          />
                        </TableCell>
                        <TableCell>
                          {formatPrivacyDate(request.requestedAt)}
                        </TableCell>
                        <TableCell>
                          <Typography variant="body2" noWrap>
                            {request.description}
                          </Typography>
                        </TableCell>
                        <TableCell>
                          <IconButton
                            size="small"
                            aria-label="View request"
                            onClick={() => {
                              setSelectedRequest(request);
                              setOpenRequestDetailsDialog(true);
                            }}
                          >
                            <ViewIcon />
                          </IconButton>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollableTableContainer>
            </Grid>
          )}
        </Grid>
      )}

      {/* Activity Log Tab */}
      {activeTab === 2 && (
        <Grid container spacing={3} role="tabpanel" id="data-privacy-panel-2" aria-labelledby="data-privacy-tab-2">
          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom>
              Data Activity Log
            </Typography>
          </Grid>

          {activitiesStatus === 'loading' || activitiesStatus === 'idle' ? (
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
                <CircularProgress aria-label="Loading activity log" />
              </Box>
            </Grid>
          ) : activitiesStatus === 'error' ? (
            <Grid item xs={12}>
              <Alert severity="error" action={<Button size="small" onClick={() => { void loadDataActivities(); }}>Retry</Button>}>
                {activitiesError || 'Failed to load the activity log.'}
              </Alert>
            </Grid>
          ) : dataActivities.length === 0 ? (
            <Grid item xs={12}>
              <Alert severity="info">
                No privacy / DSAR activity entries yet. Document uploads and assessments appear in their
                own modules; this log lists data-rights and privacy events when they occur.
              </Alert>
            </Grid>
          ) : (
            <Grid item xs={12}>
              <List>
                {dataActivities.map((activity) => (
                  <ListItem key={activity._id} divider>
                    <ListItemIcon>
                      <TimelineIcon color="primary" />
                    </ListItemIcon>
                    <ListItemText
                      primary={activity.action}
                      secondary={
                        <Box>
                          <Typography variant="body2" color="text.secondary">
                            {activity.dataType} • {activityDate(activity)}
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {activity.details}
                          </Typography>
                        </Box>
                      }
                    />
                  </ListItem>
                ))}
              </List>
            </Grid>
          )}
        </Grid>
      )}

      {/* Consent Management Tab */}
      {activeTab === 3 && (
        <Grid container spacing={3} role="tabpanel" id="data-privacy-panel-3" aria-labelledby="data-privacy-tab-3">
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Consent Management
                </Typography>
                {settingsBlocked ? (
                  <Alert
                    severity={settingsStatus === 'error' ? 'error' : 'info'}
                    action={settingsStatus === 'error' ? <Button size="small" onClick={() => { void loadPrivacySettings(); }}>Retry</Button> : undefined}
                  >
                    {settingsStatus === 'error'
                      ? (settingsError || 'Failed to load privacy settings.')
                      : 'Loading privacy settings…'}
                  </Alert>
                ) : (
                <form onSubmit={handleSubmit(savePrivacySettings)}>
                  <Grid container spacing={3}>
                    <Grid item xs={12} md={6}>
                      <Controller
                        name="dataProcessing"
                        control={control}
                        render={({ field }) => (
                          <FormControlLabel
                            control={<Switch {...field} checked={field.value} inputProps={{ 'aria-describedby': 'consent-data-processing-help' }} />}
                            label="Data Processing Consent"
                            sx={{ display: 'block' }}
                          />
                        )}
                      />
                      <Typography id="consent-data-processing-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                        Allow processing of personal data for service provision
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <Controller
                        name="marketingCommunications"
                        control={control}
                        render={({ field }) => (
                          <FormControlLabel
                            control={<Switch {...field} checked={field.value} inputProps={{ 'aria-describedby': 'consent-marketing-help' }} />}
                            label="Marketing Communications"
                            sx={{ display: 'block' }}
                          />
                        )}
                      />
                      <Typography id="consent-marketing-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                        Receive marketing emails and promotional content
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <Controller
                        name="thirdPartySharing"
                        control={control}
                        render={({ field }) => (
                          <FormControlLabel
                            control={<Switch {...field} checked={field.value} inputProps={{ 'aria-describedby': 'consent-third-party-help' }} />}
                            label="Third-Party Data Sharing"
                            sx={{ display: 'block' }}
                          />
                        )}
                      />
                      <Typography id="consent-third-party-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                        Allow sharing data with trusted third-party partners
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <Controller
                        name="analyticsTracking"
                        control={control}
                        render={({ field }) => (
                          <FormControlLabel
                            control={<Switch {...field} checked={field.value} inputProps={{ 'aria-describedby': 'consent-analytics-help' }} />}
                            label="Analytics Tracking"
                            sx={{ display: 'block' }}
                          />
                        )}
                      />
                      <Typography id="consent-analytics-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                        Allow analytics and usage tracking for service improvement
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <Controller
                        name="cookieConsent"
                        control={control}
                        render={({ field }) => (
                          <FormControlLabel
                            control={<Switch {...field} checked={field.value} inputProps={{ 'aria-describedby': 'consent-cookie-help' }} />}
                            label="Cookie Consent"
                            sx={{ display: 'block' }}
                          />
                        )}
                      />
                      <Typography id="consent-cookie-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                        Allow cookies for enhanced user experience
                      </Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <Controller
                        name="dataRetention"
                        control={control}
                        render={({ field }) => (
                          <FormControlLabel
                            control={<Switch {...field} checked={field.value} inputProps={{ 'aria-describedby': 'consent-retention-help' }} />}
                            label="Data Retention"
                            sx={{ display: 'block' }}
                          />
                        )}
                      />
                      <Typography id="consent-retention-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                        Allow data retention for regulatory compliance
                      </Typography>
                    </Grid>
                  </Grid>

                  <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end' }}>
                    <Button
                      type="submit"
                      variant="contained"
                      disabled={isSaving}
                      startIcon={isSaving ? <CircularProgress size={20} /> : <CheckIcon />}
                    >
                      {isSaving ? 'Saving...' : 'Save Consent Settings'}
                    </Button>
                  </Box>
                </form>
                )}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Security Settings Tab */}
      {activeTab === 4 && (
        <Grid container spacing={3} role="tabpanel" id="data-privacy-panel-4" aria-labelledby="data-privacy-tab-4">
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Security Settings
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  These values are stored preferences. Saving them does not turn login MFA on or off, change encryption, start or stop activity recording, or change automatic logout.
                </Typography>
                {settingsBlocked || !securityDraft ? (
                  <Alert
                    severity={settingsStatus === 'error' ? 'error' : 'info'}
                    action={settingsStatus === 'error' ? <Button size="small" onClick={() => { void loadPrivacySettings(); }}>Retry</Button> : undefined}
                  >
                    {settingsStatus === 'error'
                      ? (settingsError || 'Failed to load privacy settings.')
                      : 'Loading privacy settings…'}
                  </Alert>
                ) : (
                <Grid container spacing={3}>
                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={securityDraft.twoFactorAuth}
                          onChange={(e) => setSecurityDraft({
                            ...securityDraft,
                            twoFactorAuth: e.target.checked
                          })}
                          inputProps={{ 'aria-describedby': 'security-mfa-preference-help' }}
                        />
                      }
                      label="Two-factor preference"
                      sx={{ display: 'block' }}
                    />
                    <Typography id="security-mfa-preference-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                      Stored preference only. Login MFA is controlled separately.
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={securityDraft.dataEncryption}
                          onChange={(e) => setSecurityDraft({
                            ...securityDraft,
                            dataEncryption: e.target.checked
                          })}
                          inputProps={{ 'aria-describedby': 'security-encryption-preference-help' }}
                        />
                      }
                      label="Data encryption preference"
                      sx={{ display: 'block' }}
                    />
                    <Typography id="security-encryption-preference-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                      Stored preference only. This does not change encryption at rest or HTTPS.
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={securityDraft.auditLogging}
                          onChange={(e) => setSecurityDraft({
                            ...securityDraft,
                            auditLogging: e.target.checked
                          })}
                          inputProps={{ 'aria-describedby': 'security-audit-preference-help' }}
                        />
                      }
                      label="Audit logging preference"
                      sx={{ display: 'block' }}
                    />
                    <Typography id="security-audit-preference-help" variant="body2" color="text.secondary" sx={{ ml: 4 }}>
                      Stored preference only. This does not start or stop activity recording.
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel id="privacy-session-timeout-label">Session timeout preference</InputLabel>
                      <Select
                        labelId="privacy-session-timeout-label"
                        value={securityDraft.sessionTimeout}
                        onChange={(e) => setSecurityDraft({
                          ...securityDraft,
                          sessionTimeout: Number(e.target.value)
                        })}
                        label="Session timeout preference"
                        inputProps={{ 'aria-describedby': 'security-timeout-preference-help' }}
                      >
                        <MenuItem value={15}>15 minutes</MenuItem>
                        <MenuItem value={30}>30 minutes</MenuItem>
                        <MenuItem value={60}>1 hour</MenuItem>
                        <MenuItem value={120}>2 hours</MenuItem>
                        <MenuItem value={480}>8 hours</MenuItem>
                      </Select>
                    </FormControl>
                    <Typography id="security-timeout-preference-help" variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                      Stored preference only. This does not change automatic logout.
                    </Typography>
                  </Grid>
                  <Grid item xs={12}>
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                      <Button
                        variant="contained"
                        startIcon={isSavingSecurity ? <CircularProgress size={20} /> : <SettingsIcon />}
                        disabled={isSavingSecurity}
                        onClick={() => { void saveSecurityPreferences(); }}
                      >
                        {isSavingSecurity ? 'Saving...' : 'Save Security Settings'}
                      </Button>
                    </Box>
                  </Grid>
                </Grid>
                )}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      <Dialog
        open={openSettingsDialog}
        onClose={() => setOpenSettingsDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Privacy settings</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ pt: 1 }}>
            Consent toggles and saving are available under the Consent Management tab.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSettingsDialog(false)}>Close</Button>
          <Button
            variant="contained"
            onClick={() => {
              setOpenSettingsDialog(false);
              setActiveTab(3);
            }}
          >
            Open consent settings
          </Button>
        </DialogActions>
      </Dialog>

      {/* Data Request Dialog */}
      <Dialog
        open={openRequestDialog}
        onClose={() => {
          setOpenRequestDialog(false);
          setRequestFormType('');
          setRequestFormDescription('');
        }}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          {requestFormType === 'erasure'
            ? 'Request erasure / deletion'
            : requestFormType === 'correction'
              ? 'Request correction'
              : 'Submit Data Request'}
        </DialogTitle>
        <DialogContent>
          {requestFormType === 'erasure' ? (
            <Alert severity="warning" sx={{ mt: 1, mb: 1 }}>
              Erasure may remove personal data tied to your account, uploaded documents, and workspace
              history. Some records may be retained where law requires. This action is not easily reversible.
            </Alert>
          ) : null}
          {requestFormError ? (
            <Alert severity="error" sx={{ mt: 1, mb: 1 }}>
              {requestFormError}
            </Alert>
          ) : null}
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12}>
              <FormControl fullWidth>
                <InputLabel>Request Type</InputLabel>
                <Select
                  value={requestFormType}
                  label="Request Type"
                  onChange={(e) => setRequestFormType(e.target.value)}
                >
                  <MenuItem value="access">Data Access Request (DPDP)</MenuItem>
                  <MenuItem value="data_portability">Data Portability Request (DPDP)</MenuItem>
                  <MenuItem value="correction">Data Correction Request (DPDP)</MenuItem>
                  <MenuItem value="erasure">Erasure / Deletion Request (DPDP)</MenuItem>
                  <MenuItem value="grievance">Privacy Grievance (DPDP)</MenuItem>
                  <MenuItem value="consent_withdrawal">Consent Withdrawal (DPDP)</MenuItem>
                  <MenuItem value="restriction">Processing Restriction Request (DPDP)</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                multiline
                rows={4}
                label="Description"
                placeholder="Please describe your request in detail..."
                value={requestFormDescription}
                onChange={(e) => setRequestFormDescription(e.target.value)}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => {
              setOpenRequestDialog(false);
              setRequestFormType('');
              setRequestFormDescription('');
            }}
          >
            Cancel
          </Button>
          <Button
            variant="contained"
            disabled={isSubmittingRequest || !requestFormType.trim() || !requestFormDescription.trim()}
            onClick={() => {
              if (!requestFormType.trim()) {
                setRequestFormError('Please select a request type.');
                return;
              }
              if (!requestFormDescription.trim()) {
                setRequestFormError('Please describe your request.');
                return;
              }
              setRequestFormError(null);
              submitDataRequest({
                type: requestFormType,
                description: requestFormDescription.trim(),
              });
            }}
            >
            {isSubmittingRequest ? 'Submitting...' : 'Submit Request'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Request Details Dialog */}
      <Dialog open={openRequestDetailsDialog} onClose={() => setOpenRequestDetailsDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>Request Details</DialogTitle>
        <DialogContent>
          {selectedRequest && (
            <Box>
              <Grid container spacing={3}>
                <Grid item xs={12} md={6}>
                  <Typography variant="subtitle1" gutterBottom>
                    Request Information
                  </Typography>
                  <List dense>
                    <ListItem>
                      <ListItemText
                        primary="Request Type"
                        secondary={getRequestTypeLabel(selectedRequest.type)}
                      />
                    </ListItem>
                    <ListItem>
                      <ListItemText
                        primary="Status"
                        secondary={
                          <Chip
                            label={selectedRequest.status.replace('_', ' ').toUpperCase()}
                            color={getStatusColor(selectedRequest.status) as any}
                            size="small"
                          />
                        }
                      />
                    </ListItem>
                    <ListItem>
                      <ListItemText
                        primary="Requested Date"
                        secondary={formatPrivacyDate(selectedRequest.requestedAt)}
                      />
                    </ListItem>
                    {selectedRequest.completedAt && (
                      <ListItem>
                        <ListItemText
                          primary="Completed Date"
                          secondary={formatPrivacyDate(selectedRequest.completedAt)}
                        />
                      </ListItem>
                    )}
                  </List>
                </Grid>
                <Grid item xs={12} md={6}>
                  <Typography variant="subtitle1" gutterBottom>
                    Description
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {selectedRequest.description}
                  </Typography>
                  {selectedRequest.response && (
                    <Box sx={{ mt: 2 }}>
                      <Typography variant="subtitle1" gutterBottom>
                        Response
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        {selectedRequest.response}
                      </Typography>
                    </Box>
                  )}
                </Grid>
              </Grid>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          {selectedRequest && ['erasure', 'delete', 'deletion'].includes(selectedRequest.type) && selectedRequest.status === 'pending' ? (
            <Button
              color="warning"
              disabled={dsarBusy}
              onClick={() => acknowledgeErasure(selectedRequest._id)}
            >
              Acknowledge erasure processing
            </Button>
          ) : null}
          <Button onClick={() => setOpenRequestDetailsDialog(false)}>
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default DataPrivacy;